class Solution {
    struct Job {
        int start, end, profit;
    };
public:
    int jobScheduling(vector<int>& startTime, vector<int>& endTime, vector<int>& profit) {
        int n = startTime.size();
        vector<Job> jobs(n);
        for (int i = 0; i < n; i++) {
            jobs[i] = {startTime[i], endTime[i], profit[i]};
        }
        sort(jobs.begin(), jobs.end(), [](const Job& a, const Job& b) {
            return a.start < b.start;
        });
        vector<int> starts(n);
        for (int i = 0; i < n; i++) starts[i] = jobs[i].start;

        vector<long long> dp(n + 1, 0);
        for (int i = n - 1; i >= 0; i--) {
            int j = lower_bound(starts.begin(), starts.end(), jobs[i].end) - starts.begin();
            dp[i] = max(dp[i + 1], (long long)jobs[i].profit + dp[j]);
        }
        return (int)dp[0];
    }
};
